  /// Adds a fallback Roboto font to the bundle and registers it in the
  /// `FontManifest.json` file.
  ///
  /// This is used when a locally-bundled CanvasKit is requested so that text
  /// can be rendered without any additional developer configuration.
  void _bundleFallbackRobotoFont(Environment environment, Directory outputDirectory) {
    final FileSystem fileSystem = environment.fileSystem;

    const String robotoAsset = 'fonts/fallback/Roboto-Regular.ttf';

    // Update FontManifest.json to include the fallback Roboto font, avoiding
    // duplicate entries if it is already present.
    final File fontManifestFile = outputDirectory.childFile('FontManifest.json');
    final fontManifest = <Object?>[];
    if (fontManifestFile.existsSync()) {
      final Object? decoded = jsonDecode(fontManifestFile.readAsStringSync());
      if (decoded is List) {
        fontManifest.addAll(decoded);
      }
    }

    final bool hasRoboto = fontManifest.any(
      (Object? entry) => entry is Map && entry['family'] == 'Roboto',
    );
    if (!hasRoboto) {
      fontManifest.add(<String, Object?>{
        'family': 'Roboto',
        'fonts': <Object?>[
          <String, Object?>{'asset': robotoAsset},
        ],
      });
      fontManifestFile.writeAsStringSync(jsonEncode(fontManifest));
    }

    // Copy the Roboto font file out of the Flutter engine source tree.
    final File robotoSource = fileSystem.file(
      fileSystem.path.join(
        Cache.flutterRoot!,
        'engine',
        'src',
        'flutter',
        'txt',
        'third_party',
        'fonts',
        'Roboto-Regular.ttf',
      ),
    );
    final File robotoDestination = fileSystem.file(
      fileSystem.path.join(outputDirectory.path, 'fonts', 'fallback', 'Roboto-Regular.ttf'),
    );
    if (!robotoDestination.parent.existsSync()) {
      robotoDestination.parent.createSync(recursive: true);
    }
    robotoSource.copySync(robotoDestination.path);
  }
